import { getImgFromURL, getFalseColor } from '../../../../lib';
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// Vertex Shader
const vertexShader = `
  attribute vec3 velocity;
  attribute float density;
  varying vec3 vColor;
  varying float vAlpha;
  
  void main() {
    float speed = length(velocity);
    float speedNorm = clamp(speed * 2.0, 0.0, 1.0);
    float densNorm = clamp(density * 0.3, 0.0, 1.0);
    
    // 속도 기반 색상: 파란색(느림) -> 초록 -> 노란색 -> 빨간색(빠름)
    if (speedNorm < 0.33) {
      vColor = mix(vec3(0.2, 0.2, 1.0), vec3(0.2, 1.0, 0.5), speedNorm * 3.0);
    } else if (speedNorm < 0.66) {
      vColor = mix(vec3(0.2, 1.0, 0.5), vec3(1.0, 1.0, 0.2), (speedNorm - 0.33) * 3.0);
    } else {
      vColor = mix(vec3(1.0, 1.0, 0.2), vec3(1.0, 0.2, 0.2), (speedNorm - 0.66) * 3.0);
    }
    
    vAlpha = clamp(speedNorm + densNorm * 0.5, 0.2, 0.9);
    
    vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
    gl_PointSize = 8.0 * (1.0 + speedNorm) * (300.0 / -mvPosition.z);
    gl_Position = projectionMatrix * mvPosition;
  }
`;

// Fragment Shader
const fragmentShader = `
  varying vec3 vColor;
  varying float vAlpha;
  
  void main() {
    vec2 center = gl_PointCoord - vec2(0.5);
    float dist = length(center);
    if (dist > 0.5) discard;
    
    float alpha = vAlpha * (1.0 - dist * 2.0);
    gl_FragColor = vec4(vColor, alpha);
  }
`;

// ── 3D Fluid 클래스 ────────────────────────────────────
class Fluid3D {
	N;
	iter;
	dt;
	diff;
	visc;
	visScale;
	s;
	density;
	Vx;
	Vy;
	Vz;
	Vx0;
	Vy0;
	Vz0;
	cellFixed;
	constructor(dt = 0.015, diffusion = 0, viscosity = 0.0000001) {
		this.N = 24; // 24^3 = 13,824 cells
		this.iter = 6;
		this.dt = dt;
		this.diff = diffusion;
		this.visc = viscosity;
		this.visScale = 0.01; // 2D 코드와 동일

		const size = this.N * this.N * this.N;
		this.s = new Float32Array(size);
		this.density = new Float32Array(size);
		this.Vx = new Float32Array(size);
		this.Vy = new Float32Array(size);
		this.Vz = new Float32Array(size);
		this.Vx0 = new Float32Array(size);
		this.Vy0 = new Float32Array(size);
		this.Vz0 = new Float32Array(size);
		this.cellFixed = [];
	}

	step() {
		diffuse3D(1, this.Vx0, this.Vx, this.visc, this.dt, this.N, this.iter, this.cellFixed);
		diffuse3D(2, this.Vy0, this.Vy, this.visc, this.dt, this.N, this.iter, this.cellFixed);
		diffuse3D(3, this.Vz0, this.Vz, this.visc, this.dt, this.N, this.iter, this.cellFixed);

		project3D(this.Vx0, this.Vy0, this.Vz0, this.Vx, this.Vy, this.Vz, this.N, this.iter, this.cellFixed);

		advect3D(1, this.Vx, this.Vx0, this.Vx0, this.Vy0, this.Vz0, this.dt, this.N, this.cellFixed);
		advect3D(2, this.Vy, this.Vy0, this.Vx0, this.Vy0, this.Vz0, this.dt, this.N, this.cellFixed);
		advect3D(3, this.Vz, this.Vz0, this.Vx0, this.Vy0, this.Vz0, this.dt, this.N, this.cellFixed);

		project3D(this.Vx, this.Vy, this.Vz, this.Vx0, this.Vy0, this.Vz0, this.N, this.iter, this.cellFixed);

		diffuse3D(0, this.s, this.density, this.diff, this.dt, this.N, this.iter, this.cellFixed);
		advect3D(0, this.density, this.s, this.Vx, this.Vy, this.Vz, this.dt, this.N, this.cellFixed);
	}

	addDensity(x, y, z, amount) {
		if (x < 0 || x >= this.N || y < 0 || y >= this.N || z < 0 || z >= this.N) return;
		this.density[IX3D(x, y, z, this.N)] += amount;
	}

	addVelocity(x, y, z, vx, vy, vz) {
		if (x < 0 || x >= this.N || y < 0 || y >= this.N || z < 0 || z >= this.N) return;
		const idx = IX3D(x, y, z, this.N);
		this.Vx[idx] += vx;
		this.Vy[idx] += vy;
		this.Vz[idx] += vz;
	}

	reset() {
		this.density.fill(0);
		this.Vx.fill(0);
		this.Vy.fill(0);
		this.Vz.fill(0);
		this.Vx0.fill(0);
		this.Vy0.fill(0);
		this.Vz0.fill(0);
		this.s.fill(0);
		this.cellFixed = [];
	}

	getVelocityAt(x, y, z) {
		if (x < 0 || x >= this.N || y < 0 || y >= this.N || z < 0 || z >= this.N) return { vx: 0, vy: 0, vz: 0 };
		const idx = IX3D(Math.floor(x), Math.floor(y), Math.floor(z), this.N);
		return { vx: this.Vx[idx], vy: this.Vy[idx], vz: this.Vz[idx] };
	}

	getDensityAt(x, y, z) {
		if (x < 0 || x >= this.N || y < 0 || y >= this.N || z < 0 || z >= this.N) return 0;
		return this.density[IX3D(Math.floor(x), Math.floor(y), Math.floor(z), this.N)];
	}
}

const IX3D = (x, y, z, N) => x + y * N + z * N * N;

function set_bnd3D(b, arr, N, fixedCells) {
	for (let zz = 1; zz < N - 1; zz++) {
		for (let yy = 1; yy < N - 1; yy++) {
			arr[IX3D(0, yy, zz, N)] = b === 1 ? -arr[IX3D(1, yy, zz, N)] : arr[IX3D(1, yy, zz, N)];
			arr[IX3D(N - 1, yy, zz, N)] = b === 1 ? -arr[IX3D(N - 2, yy, zz, N)] : arr[IX3D(N - 2, yy, zz, N)];
		}
	}
	for (let zz = 1; zz < N - 1; zz++) {
		for (let xx = 1; xx < N - 1; xx++) {
			arr[IX3D(xx, 0, zz, N)] = b === 2 ? -arr[IX3D(xx, 1, zz, N)] : arr[IX3D(xx, 1, zz, N)];
			arr[IX3D(xx, N - 1, zz, N)] = b === 2 ? -arr[IX3D(xx, N - 2, zz, N)] : arr[IX3D(xx, N - 2, zz, N)];
		}
	}
	for (let yy = 1; yy < N - 1; yy++) {
		for (let xx = 1; xx < N - 1; xx++) {
			arr[IX3D(xx, yy, 0, N)] = b === 3 ? -arr[IX3D(xx, yy, 1, N)] : arr[IX3D(xx, yy, 1, N)];
			arr[IX3D(xx, yy, N - 1, N)] = b === 3 ? -arr[IX3D(xx, yy, N - 2, N)] : arr[IX3D(xx, yy, N - 2, N)];
		}
	}

	if (!Array.isArray(fixedCells) || fixedCells.length === 0) return;

	const fixedSet = new Set(fixedCells.map(([i, j, k]) => IX3D(i, j, k, N)));
	for (const [i, j, k] of fixedCells) {
		if (i < 1 || i > N - 2 || j < 1 || j > N - 2 || k < 1 || k > N - 2) continue;
		arr[IX3D(i, j, k, N)] = 0;
	}
}

function diffuse3D(b, x, x0, diff, dt, N, iter, fixed) {
	const a = dt * diff * (N - 2) ** 3;
	lin_solve3D(b, x, x0, a, 1 + 6 * a, N, iter, fixed);
}

function lin_solve3D(b, x, x0, a, c, N, iter, fixed) {
	const cRecip = 1 / c;
	for (let t = 0; t < iter; t++) {
		for (let k = 1; k < N - 1; k++)
			for (let j = 1; j < N - 1; j++)
				for (let i = 1; i < N - 1; i++) {
					const idx = IX3D(i, j, k, N);
					x[idx] =
						(x0[idx] + a * (x[IX3D(i + 1, j, k, N)] + x[IX3D(i - 1, j, k, N)] + x[IX3D(i, j + 1, k, N)] + x[IX3D(i, j - 1, k, N)] + x[IX3D(i, j, k + 1, N)] + x[IX3D(i, j, k - 1, N)])) *
						cRecip;
				}
		set_bnd3D(b, x, N, fixed);
	}
}

function project3D(ux, uy, uz, p, div, N, iter, fixed) {
	for (let k = 1; k < N - 1; k++)
		for (let j = 1; j < N - 1; j++)
			for (let i = 1; i < N - 1; i++) {
				const idx = IX3D(i, j, k, N);
				div[idx] =
					(-0.5 * (ux[IX3D(i + 1, j, k, N)] - ux[IX3D(i - 1, j, k, N)] + uy[IX3D(i, j + 1, k, N)] - uy[IX3D(i, j - 1, k, N)] + uz[IX3D(i, j, k + 1, N)] - uz[IX3D(i, j, k - 1, N)])) / N;
				p[idx] = 0;
			}
	set_bnd3D(0, div, N, fixed);
	set_bnd3D(0, p, N, fixed);
	lin_solve3D(0, p, div, 1, 6, N, iter, fixed);

	for (let k = 1; k < N - 1; k++)
		for (let j = 1; j < N - 1; j++)
			for (let i = 1; i < N - 1; i++) {
				const idx = IX3D(i, j, k, N);
				ux[idx] -= 0.5 * (p[IX3D(i + 1, j, k, N)] - p[IX3D(i - 1, j, k, N)]) * N;
				uy[idx] -= 0.5 * (p[IX3D(i, j + 1, k, N)] - p[IX3D(i, j - 1, k, N)]) * N;
				uz[idx] -= 0.5 * (p[IX3D(i, j, k + 1, N)] - p[IX3D(i, j, k - 1, N)]) * N;
			}
	set_bnd3D(1, ux, N, fixed);
	set_bnd3D(2, uy, N, fixed);
	set_bnd3D(3, uz, N, fixed);
}

function advect3D(b, d, d0, ux, uy, uz, dt, N, fixed) {
	const dt0 = dt * (N - 2);
	for (let k = 1; k < N - 1; k++) {
		for (let j = 1; j < N - 1; j++) {
			for (let i = 1; i < N - 1; i++) {
				const idx = IX3D(i, j, k, N);
				let x = i - dt0 * ux[idx];
				let y = j - dt0 * uy[idx];
				let z = k - dt0 * uz[idx];

				x = Math.max(0.5, Math.min(N - 1.5, x));
				y = Math.max(0.5, Math.min(N - 1.5, y));
				z = Math.max(0.5, Math.min(N - 1.5, z));

				const i0 = Math.floor(x),
					i1 = i0 + 1;
				const j0 = Math.floor(y),
					j1 = j0 + 1;
				const k0 = Math.floor(z),
					k1 = k0 + 1;

				const s1 = x - i0,
					s0 = 1 - s1;
				const t1 = y - j0,
					t0 = 1 - t1;
				const u1 = z - k0,
					u0 = 1 - u1;

				d[idx] =
					s0 * (t0 * (u0 * d0[IX3D(i0, j0, k0, N)] + u1 * d0[IX3D(i0, j0, k1, N)]) + t1 * (u0 * d0[IX3D(i0, j1, k0, N)] + u1 * d0[IX3D(i0, j1, k1, N)])) +
					s1 * (t0 * (u0 * d0[IX3D(i1, j0, k0, N)] + u1 * d0[IX3D(i1, j0, k1, N)]) + t1 * (u0 * d0[IX3D(i1, j1, k0, N)] + u1 * d0[IX3D(i1, j1, k1, N)]));
			}
		}
	}
	set_bnd3D(b, d, N, fixed);
}

export class FluidSystem3D {
	scene: Scene;
	camera: THREE.PerspectiveCamera;
	renderer: WebGLRenderer;
	controls: OrbitControls;
	fluid: Fluid3D;
	buildingMeshes = [];
	emitters;
	windDirX;
	windDirZ;
	windStrength;
	showVectors;
	raycaster;
	pointer;
	lastTime;
	frameCount;

	particleCount;
	particleSystem;
	constructor(div) {
		const divUI = document.createElement('div');
		divUI.style.position = 'absolute';
		div.appendChild(divUI);

		this.scene = new THREE.Scene();
		this.scene.background = new THREE.Color(0x050510);
		this.scene.fog = new THREE.Fog(0x050510, 20, 80);

		this.camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
		this.camera.position.set(35, 25, 35);

		this.renderer = new THREE.WebGLRenderer({ antialias: true });
		this.renderer.setSize(window.innerWidth, window.innerHeight);
		this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
		div.appendChild(this.renderer.domElement);

		this.controls = new OrbitControls(this.camera, this.renderer.domElement);
		this.controls.enableDamping = true;
		this.controls.dampingFactor = 0.05;
		this.controls.target.set(12, 6, 12);
		this.controls.maxDistance = 100;
		this.controls.minDistance = 10;
		this.controls.update();

		this.fluid = new Fluid3D();

		this.buildingMeshes = [];
		this.emitters = [[2, Math.floor(this.fluid.N * 0.5), Math.floor(this.fluid.N * 0.5)]];
		this.windDirX = 1;
		this.windDirZ = 0;
		this.windStrength = 0.5;
		this.showVectors = false;

		this.addBuildings();
		this.createParticleSystem();
		this.createVectorField();
		this.createBuildingMeshes();

		this.raycaster = new THREE.Raycaster();
		this.pointer = new THREE.Vector2();

		window.addEventListener('click', this.onClick.bind(this));

		window.addEventListener('resize', () => {
			this.camera.aspect = window.innerWidth / window.innerHeight;
			this.camera.updateProjectionMatrix();
			this.renderer.setSize(window.innerWidth, window.innerHeight);
		});

		this.initUI(divUI);
		this.lastTime = performance.now();
		this.frameCount = 0;
	}

	addBuildings() {
		// 건물 1: 4x12x4 at (8,0,8)
		for (let x = 8; x < 12; x++) for (let y = 0; y < 12; y++) for (let z = 8; z < 12; z++) this.fluid.cellFixed.push([x, y, z]);

		// 건물 2: 6x16x6 at (16,0,4)
		for (let x = 16; x < 22; x++) for (let y = 0; y < 16; y++) for (let z = 4; z < 10; z++) this.fluid.cellFixed.push([x, y, z]);

		// 건물 3: 5x10x5 at (5,0,16)
		for (let x = 5; x < 10; x++) for (let y = 0; y < 10; y++) for (let z = 16; z < 21; z++) this.fluid.cellFixed.push([x, y, z]);

		console.log(`Fixed cells: ${this.fluid.cellFixed.length}`);
	}

	createParticleSystem() {
		const positions = [];
		const step = 1; // 더 촘촘하게

		for (let x = 0; x < this.fluid.N; x += step) {
			for (let y = 0; y < this.fluid.N; y += step) {
				for (let z = 0; z < this.fluid.N; z += step) {
					positions.push(x, y, z);
				}
			}
		}

		this.particleCount = positions.length / 3;

		const geometry = new THREE.BufferGeometry();
		geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
		geometry.setAttribute('velocity', new THREE.Float32BufferAttribute(new Float32Array(positions.length), 3));
		geometry.setAttribute('density', new THREE.Float32BufferAttribute(new Float32Array(this.particleCount), 1));

		const material = new THREE.ShaderMaterial({
			vertexShader,
			fragmentShader,
			transparent: true,
			depthWrite: false,
			blending: THREE.AdditiveBlending,
		});

		this.particleSystem = new THREE.Points(geometry, material);
		this.scene.add(this.particleSystem);
	}
	vectorPositions;
	vectorColors;
	vectorLines;
	vectorStep;
	createVectorField() {
		// 벡터 라인 생성 (2D 코드의 renderV와 유사)
		const vectorGeometry = new THREE.BufferGeometry();
		const step = 3; // 벡터 간격
		const maxVectors = Math.floor(this.fluid.N / step) ** 3;

		this.vectorPositions = new Float32Array(maxVectors * 6); // 라인이므로 2개 점 * 3 좌표
		this.vectorColors = new Float32Array(maxVectors * 6); // 각 점마다 색상

		vectorGeometry.setAttribute('position', new THREE.Float32BufferAttribute(this.vectorPositions, 3));
		vectorGeometry.setAttribute('color', new THREE.Float32BufferAttribute(this.vectorColors, 3));

		const vectorMaterial = new THREE.LineBasicMaterial({
			vertexColors: true,
			linewidth: 2,
			transparent: true,
			opacity: 0.7,
		});

		this.vectorLines = new THREE.LineSegments(vectorGeometry, vectorMaterial);
		this.vectorLines.visible = false;
		this.scene.add(this.vectorLines);

		this.vectorStep = step;
	}

	createBuildingMeshes() {
		const buildingMaterial = new THREE.MeshStandardMaterial({
			color: 0x333344,
			roughness: 0.8,
			metalness: 0.2,
			emissive: 0x112233,
			emissiveIntensity: 0.2,
		});

		const box1 = new THREE.Mesh(new THREE.BoxGeometry(4, 12, 4), buildingMaterial);
		box1.position.set(10, 6, 10);
		box1.castShadow = true;
		this.scene.add(box1);
		this.buildingMeshes.push(box1);

		const box2 = new THREE.Mesh(new THREE.BoxGeometry(6, 16, 6), buildingMaterial);
		box2.position.set(19, 8, 7);
		box2.castShadow = true;
		this.scene.add(box2);
		this.buildingMeshes.push(box2);

		const box3 = new THREE.Mesh(new THREE.BoxGeometry(5, 10, 5), buildingMaterial);
		box3.position.set(7.5, 5, 18.5);
		box3.castShadow = true;
		this.scene.add(box3);
		this.buildingMeshes.push(box3);

		// 바닥
		const ground = new THREE.Mesh(new THREE.PlaneGeometry(this.fluid.N, this.fluid.N), new THREE.MeshStandardMaterial({ color: 0x0a0a15, roughness: 0.9 }));
		ground.rotation.x = -Math.PI / 2;
		ground.receiveShadow = true;
		this.scene.add(ground);

		// 조명
		const light1 = new THREE.DirectionalLight(0xffffff, 1);
		light1.position.set(50, 50, 50);
		light1.castShadow = true;
		this.scene.add(light1);

		const light2 = new THREE.DirectionalLight(0x6699ff, 0.3);
		light2.position.set(-30, 20, -30);
		this.scene.add(light2);

		this.scene.add(new THREE.AmbientLight(0x223344, 0.4));

		// 그리드
		const grid = new THREE.GridHelper(this.fluid.N, this.fluid.N, 0x1a2a3a, 0x0f1a25);
		grid.position.y = 0.01;
		this.scene.add(grid);
	}

	onClick(e) {
		this.pointer.x = (e.clientX / window.innerWidth) * 2 - 1;
		this.pointer.y = -(e.clientY / window.innerHeight) * 2 + 1;

		this.raycaster.setFromCamera(this.pointer, this.camera);
		const intersects = this.raycaster.intersectObjects(this.buildingMeshes);

		if (intersects.length > 0) {
			const point = intersects[0].point;
			const x = Math.floor(Math.max(0, Math.min(this.fluid.N - 1, point.x)));
			const y = Math.floor(Math.max(0, Math.min(this.fluid.N - 1, point.y)));
			const z = Math.floor(Math.max(0, Math.min(this.fluid.N - 1, point.z)));
			this.emitters.push([x, y, z]);
			console.log(`Added emitter at (${x}, ${y}, ${z})`);
		}
	}

	initUI(container) {
		container.innerHTML = '<h3>GPU Wind Simulation</h3>';

		const btnReset = document.createElement('button');
		btnReset.textContent = 'Reset';
		btnReset.onclick = () => {
			this.fluid.reset();
			this.emitters = [[2, Math.floor(this.fluid.N * 0.5), Math.floor(this.fluid.N * 0.5)]];
			this.addBuildings();
		};
		container.appendChild(btnReset);

		this.addSlider(container, 'Wind Strength', 0.1, 2, 0.1, 0.5, (v) => (this.windStrength = v));
		this.addSlider(container, 'Wind Direction (°)', 0, 360, 1, 0, (v) => this.rotation(v));
		this.addSlider(container, 'Time Step', 0.001, 0.05, 0.001, 0.015, (v) => (this.fluid.dt = v));
		this.addSlider(container, 'Viscosity', 0, 0.0001, 0.000001, 0.0000001, (v) => (this.fluid.visc = v));
		this.addSlider(container, 'Vis Scale', 0.001, 0.1, 0.001, 0.01, (v) => (this.fluid.visScale = v));

		// Show Vectors toggle
		const divVec = document.createElement('div');
		divVec.style.marginTop = '8px';
		divVec.innerHTML = '<label><input type="checkbox" id="chkVectors"> Show Vector Lines</label>';
		container.appendChild(divVec);
		divVec.querySelector('#chkVectors').onchange = (e) => {
			this.showVectors = e.target.checked;
			if (this.vectorLines) {
				this.vectorLines.visible = this.showVectors;
			}
		};

		const info = document.createElement('div');
		info.className = 'info';
		info.innerHTML = `
      <b>Controls:</b><br>
      • Left drag: Rotate<br>
      • Right drag: Pan<br>
      • Scroll: Zoom<br>
      • Click building: Add emitter<br><br>
      <b>Color Legend:</b><br>
      Blue = Slow<br>
	  Green = Medium<br>
      Yellow = Fast<br>
      Red = Very Fast
    `;
		container.appendChild(info);

		this.fpsDiv = document.createElement('div');
		this.fpsDiv.style.marginTop = '10px';
		this.fpsDiv.style.fontSize = '12px';
		container.appendChild(this.fpsDiv);
	}

	addSlider(container, label, min, max, step, initial, callback) {
		const div = document.createElement('div');
		div.style.marginTop = '8px';
		const lbl = document.createElement('div');
		lbl.className = 'slider-label';
		lbl.textContent = label;
		div.appendChild(lbl);

		const slider = document.createElement('input');
		slider.type = 'range';
		slider.min = min;
		slider.max = max;
		slider.step = step;
		slider.value = initial;
		slider.oninput = () => callback(parseFloat(slider.value));
		div.appendChild(slider);

		container.appendChild(div);
	}

	rotation(angleDeg) {
		const rad = (angleDeg * Math.PI) / 180;
		this.windDirX = Math.cos(rad);
		this.windDirZ = Math.sin(rad);
	}

	animate() {
		requestAnimationFrame(() => this.animate());

		this.frameCount++;
		const now = performance.now();
		if (now - this.lastTime > 1000) {
			this.fpsDiv.innerHTML = `FPS: ${this.frameCount} | Particles: ${this.particleCount.toLocaleString()}`;
			this.frameCount = 0;
			this.lastTime = now;
		}

		// Add wind from emitters
		const strength = 3 + Math.random() * 2;
		for (const [cx, cy, cz] of this.emitters) {
			for (let i = -2; i <= 2; i++) for (let j = -2; j <= 2; j++) for (let k = -2; k <= 2; k++) this.fluid.addDensity(cx + i, cy + j, cz + k, strength);

			this.fluid.addVelocity(cx, cy, cz, this.windDirX * this.windStrength, 0, this.windDirZ * this.windStrength);
		}

		this.fluid.step();

		// Update particle attributes for shader
		const positions = this.particleSystem.geometry.attributes.position.array;
		const velocities = this.particleSystem.geometry.attributes.velocity.array;
		const densities = this.particleSystem.geometry.attributes.density.array;

		for (let i = 0; i < this.particleCount; i++) {
			const px = Math.floor(positions[i * 3]);
			const py = Math.floor(positions[i * 3 + 1]);
			const pz = Math.floor(positions[i * 3 + 2]);

			if (px >= 0 && px < this.fluid.N && py >= 0 && py < this.fluid.N && pz >= 0 && pz < this.fluid.N) {
				const vel = this.fluid.getVelocityAt(px, py, pz);
				velocities[i * 3] = vel.vx;
				velocities[i * 3 + 1] = vel.vy;
				velocities[i * 3 + 2] = vel.vz;
				densities[i] = this.fluid.getDensityAt(px, py, pz);
			}
		}

		this.particleSystem.geometry.attributes.velocity.needsUpdate = true;
		this.particleSystem.geometry.attributes.density.needsUpdate = true;

		// 벡터 라인 업데이트 (2D renderV와 동일한 방식)
		if (this.showVectors && this.vectorLines) {
			let lineIndex = 0;
			const step = this.vectorStep;
			const scale = 2.5; // 벡터 길이 스케일

			for (let x = 0; x < this.fluid.N; x += step) {
				for (let y = 0; y < this.fluid.N; y += step) {
					for (let z = 0; z < this.fluid.N; z += step) {
						const vel = this.fluid.getVelocityAt(x, y, z);
						const mag = Math.sqrt(vel.vx ** 2 + vel.vy ** 2 + vel.vz ** 2);

						// 2D 코드처럼 작은 벡터는 그리지 않음
						if (mag > 0.05) {
							// 시작점
							this.vectorPositions[lineIndex * 6] = x;
							this.vectorPositions[lineIndex * 6 + 1] = y;
							this.vectorPositions[lineIndex * 6 + 2] = z;

							// 끝점
							this.vectorPositions[lineIndex * 6 + 3] = x + vel.vx * scale;
							this.vectorPositions[lineIndex * 6 + 4] = y + vel.vy * scale;
							this.vectorPositions[lineIndex * 6 + 5] = z + vel.vz * scale;

							// 속도에 따른 색상 (getFalseColor 참조하여 간단히 구현)
							const speedNorm = Math.min(mag * this.fluid.visScale * 50, 1);
							const r = speedNorm;
							const g = 1 - speedNorm * 0.5;
							const b = 1 - speedNorm;

							// 시작점 색상
							this.vectorColors[lineIndex * 6] = r;
							this.vectorColors[lineIndex * 6 + 1] = g;
							this.vectorColors[lineIndex * 6 + 2] = b;

							// 끝점 색상
							this.vectorColors[lineIndex * 6 + 3] = r;
							this.vectorColors[lineIndex * 6 + 4] = g;
							this.vectorColors[lineIndex * 6 + 5] = b;

							lineIndex++;
						}
					}
				}
			}

			// 사용하지 않는 라인은 길이 0으로 설정
			for (let i = lineIndex; i < this.vectorPositions.length / 6; i++) {
				for (let j = 0; j < 6; j++) {
					this.vectorPositions[i * 6 + j] = 0;
				}
			}

			this.vectorLines.geometry.attributes.position.needsUpdate = true;
			this.vectorLines.geometry.attributes.color.needsUpdate = true;
		}

		this.controls.update();
		this.renderer.render(this.scene, this.camera);
	}
}
